def set_reaction(user, obj, new_type):
  for _ in range(3):
    row = store.get(obj, user)                       # LOCAL_QUORUM
    old = row.type if row else None
    if old == new_type:
        return State(new_type)                       # retry or no-op
    ok = store.cas(obj, user, expect_ver=row.ver if row else None,
                   type=new_type)                    # LWT IF ver = x / IF NOT EXISTS
    if ok:
        outbox.emit(Delta(obj, user, old, new_type)) # key = obj
        return State(new_type)
  raise Conflict()

def delta_of(old, new):
  v = defaultdict(int)
  if old: v[old] -= 1; v['total'] -= 1
  if new: v[new] += 1; v['total'] += 1
  return v                                          # like->love: total 0

acc = defaultdict(lambda: defaultdict(int)); last_off = {}
def on_batch(records):
  for r in records:
    if r.offset <= fence[r.partition]: continue      # already applied
    for t, n in delta_of(r.old, r.new).items():
      acc[r.object_id][t] += n
    last_off[r.partition] = r.offset
  if elapsed() > 1.0 or size(acc) > 50_000: flush()

def flush():
  pipe = redis.multi()
  for obj, vec in acc.items():
    key = shard_key(obj) if is_hot(obj) else f'cnt:{obj}'
    for t, n in vec.items():
      if n: pipe.hincrby(key, t, n)
  for p, o in last_off.items(): pipe.hset('fence', p, o)
  pipe.execute(); kafka.commit(last_off); acc.clear()

def compact(n):
  if n < 1000: return str(n)
  for div, suf in ((1e9,'B'), (1e6,'M'), (1e3,'K')):
    if n >= div:
      v = math.floor(n / div * 10) / 10            # truncate
      return f'{v:g}{suf}'
